        else:
            deps = list(dependencies)
        for dep in deps:
            if dep not in self._tasks:
                raise KeyError(dep)
        self._tasks[task_id] = {
            "status": "pending",
            "dependencies": deps,
            "comments": [],
        }
        self._order.append(task_id)

    def start(self, task_id):
