                continue
            runnable = True
            for dep in other["dependencies"]:
                if self._tasks[dep]["status"] != "completed":
                    runnable = False
                    break
            if runnable:
                self._events.append({"kind": "unblocked", "task_id": other_id})

    def add_comment(self, task_id, author, text):
