const raw = "task,owner,status\nA,alice,completed\nB,alice,pending\nC,bob,completed\nD,bob,completed\nE,bob,in_progress";
const rows = raw.trim().split("\n").slice(1);
const agg = {};
for (const line of rows) {
  const parts = line.split(",");
  const owner = parts[1];
  const status = parts[2];
  if (!agg[owner]) agg[owner] = { total: 0, completed: 0 };
  agg[owner].total += 1;
  if (status === "completed") agg[owner].completed += 1;
}
const owners = Object.keys(agg).sort();
const out = ["owner,total,completed,completion_rate"];
for (const o of owners) {
  const a = agg[o];
  out.push([o, a.total, a.completed, (a.completed / a.total).toFixed(6)].join(","));
}
const csv = out.join("\n");
text(csv);
const res = await tools.submit_progress_csv({ csv: csv });
text(typeof res === "string" ? res : JSON.stringify(res));
return;

